<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h4 mb-3">Checkout</h1><?php if ($this->session->flashdata('error')): ?><div class="alert alert-danger py-2"><?php echo html_escape($this->session->flashdata('error')); ?></div><?php endif; ?>
<?php if (!$items): ?><div class="alert alert-info">Keranjang kosong.</div><a class="btn btn-success" href="<?php echo site_url('customer/catalog'); ?>">Belanja</a><?php else: ?><form method="post" action="<?php echo site_url('customer/checkout/store'); ?>"><input type="hidden" name="<?php echo $this->security->get_csrf_token_name(); ?>" value="<?php echo $this->security->get_csrf_hash(); ?>"><div class="row g-3"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h6">Alamat Pengiriman</h2><?php if (!$addresses): ?><div class="alert alert-warning">Tambahkan alamat terlebih dahulu.</div><?php endif; ?><?php foreach ($addresses as $address): ?><div class="form-check mb-2"><input class="form-check-input" type="radio" name="address_id" id="address_<?php echo $address->id; ?>" value="<?php echo $address->id; ?>" <?php echo $address->is_primary ? 'checked' : ''; ?> required><label class="form-check-label" for="address_<?php echo $address->id; ?>"><strong><?php echo html_escape($address->label); ?></strong> - <?php echo html_escape($address->recipient_name); ?><br><span class="text-muted"><?php echo html_escape($address->address_line . ', ' . $address->city); ?></span></label></div><?php endforeach; ?><a class="btn btn-sm btn-outline-secondary" href="<?php echo site_url('customer/addresses'); ?>">Kelola Alamat</a><h2 class="h6 mt-4">Metode Pengiriman</h2><select class="form-select" name="shipping_method_id" required><option value="">- Pilih -</option><?php foreach ($shipping_methods as $method): ?><option value="<?php echo $method->id; ?>"><?php echo html_escape($method->name . ' - Rp ' . number_format((float)$method->base_cost,0,',','.')); ?></option><?php endforeach; ?></select></div></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h6">Ringkasan</h2><?php $subtotal=0; foreach ($items as $item): $line=(float)$item->selling_price*(float)$item->quantity;$subtotal+=(float)$line; ?><div class="d-flex justify-content-between border-bottom py-2"><span><?php echo html_escape($item->name); ?> x <?php echo number_format((float)$item->quantity,3,',','.'); ?></span><strong>Rp <?php echo number_format($line,0,',','.'); ?></strong></div><?php endforeach; ?><div class="d-flex justify-content-between pt-3"><strong>Subtotal</strong><strong>Rp <?php echo number_format($subtotal,0,',','.'); ?></strong></div></div><div class="card-footer"><button class="btn btn-success w-100" type="submit" <?php echo !$addresses ? 'disabled' : ''; ?>>Konfirmasi Pesanan</button></div></div></div></div></form><?php endif; ?></main></body></html>
